'use strict';
const assert=require('node:assert/strict');
const plans=require('../data/house-plans.js');
const {beforeFamilyDrawing,applyFamilyDrawing}=require('../tools/family-drawing-20261027.cjs');
const {validateFamilyDrawingShell}=require('../tools/family-drawing-shell-20261027.cjs');
const {validateFamilyDrawingElectrical}=require('../tools/family-drawing-electrical-20261027.cjs');
const p=plans.schemes.family,old=beforeFamilyDrawing(plans),f=id=>p.defaultFurniture.find(q=>q.id===id);
assert.deepEqual(applyFamilyDrawing(structuredClone(old)),plans,'Drawing revision reverses and reapplies exactly');
assert.ok(validateFamilyDrawingShell(p).ok,'CAD shell, room polygons and door/window clearances');
const electrical=validateFamilyDrawingElectrical(p);assert.ok(electrical.ok,JSON.stringify(electrical.errors));
for(const id of ['wood','laundry','screen'])assert.deepEqual(old.schemes[id],plans.schemes[id]);
assert.deepEqual([f('family-f23').w,f('family-f23').d],[1400,780]);
assert.deepEqual([f('family-f6').w,f('family-f6').d],[2410,980]);
assert.equal(f('family-f6').rot,180);assert.ok(Math.abs(f('family-f6').cy+490-9810.83)<.01);
assert.equal(f('family-f7').cx,5165);
assert.deepEqual([f('laundry_washer').w,f('laundry_washer').d,f('laundry_washer').roomId],[600,530,'bath_2']);
assert.equal(f('laundry_dryer').roomId,'balcony');assert.equal(f('balcony_robot').roomId,'living');
assert.ok(!f('balcony_recess_housing'));
assert.deepEqual([p.WIN_META.find(x=>x.id==='window_kitchen_balcony').sillMm,p.WIN_META.find(x=>x.id==='window_kitchen_balcony').heightMm],[1000,1350]);
assert.equal(p.metadata.familyDrawingBedroomsUpdate.clearancesMm.masterFrameToWardrobe,500);
assert.ok(!p.defaultFurniture.some(x=>x.type==='coffeetable'||x.type==='coffee-table'||/茶几/.test(x.name)));
console.log(JSON.stringify({status:'PASS',revision:p.metadata.familyDrawingUpdate.id,objects:p.defaultFurniture.length,electrical:electrical.counts},null,2));
